    public function fetch_markets($params = array()): array {
        /**
         * maps the most liquid verified solana $tokens to TOKEN/USDC spot markets
         *
         * @see https://dev.jup.ag/docs
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} an array of objects representing $market data
         */
        $request = array(
            'query' => 'verified',
        );
        $response = $this->publicGetTokensV2Tag($this->extend($request, $params));
        //
        //     [
        //         { "id": "So11111111111111111111111111111111111111112", "name": "Wrapped SOL", "symbol": "SOL", "decimals": 9, "liquidity": 946221959.13, "usdPrice": 116.65, ... },
        //         ...
        //     ]
        //
        // symbols are not unique even among verified tokens (two WBTC mints), keep the deepest one
        // some tokens omit liquidity, and python's sort_by raises on a missing key
        $withLiquidity = array();
        for ($i = 0; $i < count($response); $i++) {
            $withLiquidity[] = $this->extend($response[$i], array( 'liquidity' => $this->safe_number($response[$i], 'liquidity', 0) ));
        }
        $tokens = $this->sort_by($withLiquidity, 'liquidity', true);
        $quoteMint = $this->safe_string($this->options, 'quoteMint');
        $limit = $this->safe_integer($this->options, 'marketsLimit', 300);
        $result = array();
        $seen = array();
        $numMarkets = 0; // not result.length, php transpiles that to strlen
        for ($i = 0; $i < count($tokens); $i++) {
            if ($numMarkets >= $limit) {
                break;
            }
            $market = $this->parse_market($tokens[$i]);
            $symbol = $this->safe_symbol(null, $market);
            if ($this->safe_string($market, 'baseId') !== $quoteMint && !(is_array($seen) && array_key_exists($symbol ?? '', $seen))) {
                $seen[$symbol] = true;
                $result[] = $market;
                $numMarkets += 1;
            }
        }
        return $result;
    }

    public function parse_market(array $token): array {
        $baseId = $this->safe_string($token, 'id'); // mint address
        $base = $this->safe_string_upper($token, 'symbol');
        return $this->safe_market_structure(array(
            'id' => $baseId,
            'symbol' => $base . '/USDC',
            'base' => $base,
            'quote' => 'USDC',
            'baseId' => $baseId,
            'quoteId' => $this->safe_string($this->options, 'quoteMint'),
            'type' => 'spot',
            'spot' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => true,
            'contract' => false,
            'precision' => array(
                'amount' => $this->parse_number($this->parse_precision($this->safe_string($token, 'decimals'))),
                'price' => null,
            ),
            'limits' => array(
                'amount' => array( 'min' => null, 'max' => null ),
                'price' => array( 'min' => null, 'max' => null ),
                'cost' => array( 'min' => null, 'max' => null ),
                'leverage' => array( 'min' => null, 'max' => null ),
            ),
            'created' => null,
            'info' => $token,
        ));
    }

    public function fetch_ticker(string $symbol, $params = array()): array {
        /**
         * fetches the aggregated usd price of a token, only last and percentage are available
         *
         * @see https://dev.jup.ag/docs
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the ticker for
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a ~@link https://docs.ccxt.com/?id=ticker-structure ticker structure~
         */
        $this->load_markets();
        $market = $this->market($symbol);
        $request = array(
            'ids' => $market['id'],
        );
        $response = $this->publicGetPriceV3($this->extend($request, $params));
        //
        //     {
        //         "So11111111111111111111111111111111111111112": { "usdPrice": 116.64, "priceChange24h": -0.37, "liquidity": 946221959.13, "decimals": 9, "blockId": 449691427, ... }
        //     }
        //
        return $this->parse_ticker($this->safe_dict($response, $market['id'], array()), $market);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        // ponytail: usd price stands in for the USDC quote, it is not a USDC order book price
        $last = $this->safe_string($ticker, 'usdPrice');
        return $this->safe_ticker(array(
            'symbol' => $this->safe_symbol(null, $market),
            'timestamp' => null,
            'datetime' => null,
            'high' => null,
            'low' => null,
            'bid' => null,
            'bidVolume' => null,
            'ask' => null,
            'askVolume' => null,
            'vwap' => null,
            'open' => null,
            'close' => $last,
            'last' => $last,
            'previousClose' => null,
            'change' => null,
            'percentage' => $this->safe_string($ticker, 'priceChange24h'),
            'average' => null,
            'baseVolume' => null,
            'quoteVolume' => null,
            'info' => $ticker,
        ), $market);
    }

    public function create_order(string $symbol, string $type, string $side, float $amount, ?float $price = null, $params = array()): array {
        /**
         * builds an unsigned $swap transaction, it does NOT execute anything
         *
         * @see https://dev.jup.ag/docs
         *
         * @param {string} $symbol unified $symbol of the $market
         * @param {string} $type must be 'market'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount amount of the base currency to buy or sell
         * @param {float} [$price] ignored
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->userPublicKey] signer address, defaults to $this->walletAddress
         * @param {int} [$params->slippageBps] defaults to $this->options.slippageBps
         * @return {array} an ~@link https://docs.ccxt.com/?id=order-structure order structure~ with status null and the unsigned tx in info.swapTransaction
         */
        if ($type !== 'market') {
            throw new InvalidOrder($this->id . ' createOrder() supports $market orders only, use the jupiter trigger api for limit orders');
        }
        $this->load_markets();
        $market = $this->market($symbol);
        $userPublicKey = $this->safe_string($params, 'userPublicKey', $this->walletAddress);
        if ($userPublicKey === null) {
            throw new ArgumentsRequired($this->id . ' createOrder() requires $this->walletAddress or $params->userPublicKey');
        }
        $decimals = $this->safe_string($market['info'], 'decimals');
        // amount / 10^-decimals with precision 0 = integer base units, truncated
        $rawAmount = Precise::string_div($this->number_to_string($amount), $this->parse_precision($decimals), 0);
        $isSell = ($side === 'sell');
        // sell = spend exactly `amount` base, buy = receive exactly `amount` base
        $quoteRequest = array(
            'inputMint' => $isSell ? $market['baseId'] : $market['quoteId'],
            'outputMint' => $isSell ? $market['quoteId'] : $market['baseId'],
            'amount' => $rawAmount,
            'swapMode' => $isSell ? 'ExactIn' : 'ExactOut',
            'slippageBps' => $this->safe_integer($params, 'slippageBps', $this->safe_integer($this->options, 'slippageBps')),
        );
        $quote = $this->publicGetSwapV1Quote($quoteRequest);
        $swap = $this->publicPostSwapV1Swap(array(
            'quoteResponse' => $quote,
            'userPublicKey' => $userPublicKey,
            'dynamicComputeUnitLimit' => true,
        ));
        //
        //     { "swapTransaction": "AQAAAA...base64", "lastValidBlockHeight": 327711234, "prioritizationFeeLamports": 5000 }
        //
        return $this->safe_order(array(
            'id' => null, // becomes the tx signature once sent
            'symbol' => $market['symbol'],
            'type' => 'market',
            'side' => $side,
            'amount' => $amount,
            'status' => null, // nothing happened on-chain yet
            'info' => array(
                'quote' => $quote,
                'swapTransaction' => $this->safe_string($swap, 'swapTransaction'),
                'lastValidBlockHeight' => $this->safe_integer($swap, 'lastValidBlockHeight'),
            ),
        ), $market);
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): array {
        /**
         * not supported, jupiter aggregates AMMs and has no resting orders
         * @param {string} $symbol unified $symbol of the market
         * @param {int} [$limit] ignored
         * @param {array} [$params] ignored
         * @return {array} never returns
         */
        throw new NotSupported($this->id . ' fetchOrderBook() is not supported, use createOrder() quotes for executable prices');
    }

    public function sign(mixed $path, mixed $api = 'public', $method = 'GET', $params = array(), ?array $headers = null, ?string $body = null) {
        $url = $this->urls['api']['rest'] . '/' . $path;
        $headers = array();
        if ($this->apiKey !== null && $this->apiKey !== '') {
            $headers['X-API-KEY'] = $this->apiKey;
        }
        if ($method === 'GET') {
            if (count($params) > 0) {
                $url .= '?' . $this->urlencode($params);
            }
        } else {
            $body = $this->json($params);
            $headers['Content-Type'] = 'application/json';
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $httpCode, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        //
        //     { "error": "Could not find any route", "errorCode": "COULD_NOT_FIND_ANY_ROUTE" }
        //
        if ((gettype($response) !== 'array' || array_keys($response) !== array_keys(array_keys($response))) && (is_array($response) && array_key_exists('error' ?? '', $response))) {
            throw new ExchangeError($this->id . ' ' . $body);
        }
        return null;
    }
